import os


def get_app_mode():
    """Read APP_MODE from the environment, with a default fallback."""
    return os.getenv("APP_MODE", "development").strip().lower()


def main():
    mode = get_app_mode()

    if mode == "development":
        print("Debug features enabled")
    elif mode == "production":
        print("Running in production mode")
    else:
        print(f"Unknown mode: {mode}")


if __name__ == "__main__":
    main()
